\[\cos \angle AVB = \frac{AV^2 + BV^2 - AB^2}{2 \cdot AV \cdot BV} = \frac{5x^2 + 5x^2 - 16x^2}{2 \cdot x \sqrt{5} \cdot x \sqrt{5}} = \boxed{-1}.\][asy]
unitsize(4 cm);

real func (real x) {
